files.content:
html,
body {
  height: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 850px;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
}

ul {
  font-size: 20px;
  list-style-type: square;
}

/* Тут будут стили для каждого третьего пункта списка */

li:nth-child(3n) {
  color: #fd24af;
}
